<?php

namespace Agent\AgentBundle\Repository;

/**
 * AvisRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class AvisRepository extends \Doctrine\ORM\EntityRepository {

    public function getAvis($action, $agent, $state = 0) {
        if ($agent->getDirection()) {
            $direction = $agent->getDirection()->getCodeDc();
        }

        //Demande
        if ($state == 1) {
            $etat = ' IS NOT NULL ';
        } else {
            $etat = ' IS NULL ';
        }
        if ($action == 1) {
            $dql = 'SELECT d '
                    . 'FROM DemandesBundle:Demande  d '
                    . 'JOIN d.emmeteur a'
                    . ' WHERE (d.avis ' . $etat
                    . 'AND a.code_dc = :direction)'
            ;
            //Conges
        } elseif ($action == 2) {
            $dql = 'SELECT c '
                    . 'FROM AgentBundle:Conges c'
                    . ' JOIN c.agent a '
                    . ' WHERE (c.avis ' . $etat
                    . ' AND a.code_dc = :direction)'
            ;
        }

        $query = $this->_em->createQuery($dql);
        $query->setParameter('direction', $direction);
        //dump($query->getSql()); die;
        return $query->getResult();
    }

    public function findCongeParam($typeConges = 1, $serviceId, $niveau, $etat = null, $expire = 1, $agent = null) {

        $niveaux = array_values(range(5, $niveau - 1));

        if ($agent != null) {
            $matricule = ($agent->getMatricule());
        }

        $qb = $this->createQueryBuilder('c')
                ->join('c.agent', 'a');
        //->addSelect('a')
        if ($typeConges == 0) {
            if ($niveau == 0) {
//Niveau 1: Service_ Direction
                $qb->Where("a.code_dg = :Direction");
            }
            if ($niveau == 1) {
//Niveau 2; Sous Direction Section
                $qb->Where("a.code_dc = :Direction");
            }
            if ($niveau == 2) {
//Niveau 3: Direction Service Rattaché
                $qb->Where("a.code_sd = :Direction");
            }
            if ($niveau == 3) {
//Niveau 3: Direction Service Rattaché
                $qb->Where("a.code_sc = :Direction");
            }


            $qb->setParameter("Direction", $serviceId)
                    ->andWhere('c.agent <>:matricule')
                    ->setParameter("matricule", $matricule);
            if ($agent->getFonction()->getId() == 10) {
                $qb->andWhere("a.Fonction in (5,7)")
                        ->andWhere("a.Fonction in (5,7)")
                        ->orWhere("a.Direction in (12,13,14,15,16,17,18,19)");
            }
        } elseif ($typeConges == 1) {//Autres Services
            // $qb->Where("c.typeConges = :typeConges")
            $qb->Where("a.code_dc <> :Direction")
                    ->andWhere("c.niveau =0")
                    ->andWhere('a.Fonction not in (5,7)')//Directeur Chef de Service Rattaché
                    ->setParameter("Direction", $serviceId);
        } elseif ($typeConges == 2) {
            //Pour l'utilisateur connecté
        }
        //$qb->andWhere("c.niveau in (:niveau)");
        if ($etat != null and count($etat) >= 1) {
            $qb->andWhere("c.etat in (:etat)")
                    ->setParameter("etat", $etat);
        }
        if ($expire == 1) {//Actif
            $qb->andWhere("c.datereprise IS NULL ");
        } elseif ($expire == 0) {//expiré
            $qb->andWhere("c.datereprise IS NOT NULL");
        }
        $qb->orderBy('c.datecreation', 'DESC');
        //      ->setParameter("niveau", $niveaux)

        return $qb->getQuery()->getResult();
    }

}
